{"cards": [{"node_code": "N_931fcc616822cb96", "definition": "针对喀斯特地貌（岩溶地区）特有的地质条件，研究公路选线、路基处理、路面结构及防护工程的技术，重点解决溶洞、地下河、土洞等引起的路基失稳与路面病害问题。", "boundary": "本节点聚焦于岩溶地质环境下的筑路技术。边界在于区分“岩溶地质处理”与“常规路基工程”：本节点必须涉及溶洞探测、填充、注浆加固、抗滑桩等针对岩溶特性的措施；若仅涉及一般山区道路选线而未提及岩溶风险，归入高原山岭地区筑路。区分“路基处理”与“隧道工程”：若内容侧重穿越岩溶区的隧道施工，归入隧道工程；侧重地表路基与路面，归本节点。", "includes": ["岩溶区公路选线原则与避害措施", "溶洞、土洞的探测、填充与注浆加固技术", "岩溶区路基稳定性分析与抗滑、防冲蚀设计"], "excludes": ["非岩溶地区的常规路基路面工程", "岩溶区隧道、桥梁的独立结构设计与施工（归入相应结构节点）", "岩溶水文地质本身的纯地质研究（非工程应用）"], "sibling_distinctions": [{"other_code": "N_9eec13be12550bfa", "rule": "区分依据为地质成因：本节点针对可溶性岩石（如石灰岩）形成的岩溶地貌；高原山岭地区筑路针对一般山区的高差、坡度及气候影响，不特指岩溶。"}, {"other_code": "N_e32c7bbf3db844db", "rule": "区分依据为灾害类型：本节点针对静态或缓慢变形的岩溶塌陷风险；地震区筑路针对动态地震荷载下的结构抗震与液化问题。"}], "cross_boundary_rule": "若内容涉及岩溶区隧道施工，主挂载隧道工程节点，但隧道洞口及路基段的岩溶处理可关联本节点；若侧重岩溶区桥梁桩基处理，主挂载桥涵工程，但路基段归本节点。"}, {"node_code": "N_e32c7bbf3db844db", "definition": "研究在地震活跃区或高烈度区进行公路建设时，针对地震动荷载、土壤液化、滑坡崩塌等次生灾害，所采用的抗震设计原则、结构措施及施工防护技术。", "boundary": "本节点聚焦于“抗震”与“地震次生灾害防治”。边界在于区分“抗震设计”与“常规结构强度”：本节点必须涉及地震作用下的动力响应、延性设计或隔震减震措施；若仅涉及一般山区的边坡稳定而未考虑地震触发，归入高原山岭地区筑路。区分“路基抗震”与“桥梁抗震”：本节点侧重路基、路面及沿线附属设施的抗震与液化处理；桥梁结构抗震归入桥涵工程。", "includes": ["地震区公路选线避让活动断层与危险地段", "路基、路面结构的抗震设计与土壤液化防治措施", "地震诱发滑坡、崩塌的监测与防护工程"], "excludes": ["非地震区的常规边坡防护工程", "桥梁、隧道结构本身的抗震设计（归入桥涵或隧道工程）", "地震学基础理论及地震预测研究"], "sibling_distinctions": [{"other_code": "N_9eec13be12550bfa", "rule": "区分依据为荷载性质：本节点针对动态地震荷载及由此引发的次生灾害；高原山岭地区筑路针对静态重力荷载、高差及气候影响。"}, {"other_code": "N_931fcc616822cb96", "rule": "区分依据为地质背景：本节点针对地震活动性；喀斯特地区筑路针对岩溶地质缺陷。若地震区同时存在岩溶，需根据主要风险源判断，通常抗震措施归本节点，岩溶处理归喀斯特节点。"}], "cross_boundary_rule": "若内容涉及地震区桥梁抗震，主挂载桥涵工程；若涉及地震区隧道抗震，主挂载隧道工程；本节点主要收录路基、路面及沿线非结构物的抗震与次生灾害防治技术。"}, {"node_code": "N_9eec13be12550bfa", "definition": "针对高原、山岭地区高海拔、大高差、陡坡、低温缺氧及复杂地形条件，研究公路选线、路基路面结构、施工技术及环境保护的筑路技术。", "boundary": "本节点聚焦于“地形地貌”与“高海拔气候”的综合影响。边界在于区分“一般山区”与“特殊地质”：本节点涵盖非岩溶、非地震区的常规山区道路技术，如高填深挖、陡坡防护、冻融循环（非极寒区）应对；若涉及岩溶，归喀斯特节点；若涉及强震，归地震区节点。区分“高原筑路”与“冰冻地区筑路”：本节点侧重地形与高海拔综合影响；若侧重极寒气候下的冻土问题，归冰冻与严寒地区筑路。", "includes": ["高原、山岭地区公路选线、平纵面设计与高填深挖路基处理", "陡坡、高边坡的防护、加固与排水工程", "高海拔、低温缺氧环境下的施工技术与材料适应性研究"], "excludes": ["岩溶地区的特殊地质处理（归入喀斯特地区筑路）", "强震区的抗震设计与次生灾害防治（归入地震区筑路）", "极寒冻土区的特殊路基处理（归入冰冻与严寒地区筑路）"], "sibling_distinctions": [{"other_code": "N_931fcc616822cb96", "rule": "区分依据为地质特征：本节点针对一般山区地形与气候；喀斯特地区筑路针对岩溶地质缺陷。"}, {"other_code": "N_e32c7bbf3db844db", "rule": "区分依据为灾害类型：本节点针对地形与气候挑战；地震区筑路针对地震动力荷载。"}, {"other_code": "N_537dd445e590b1ba", "rule": "区分依据为气候主导因素：本节点侧重地形高差与高海拔综合影响；冰冻与严寒地区筑路侧重冻土、冰害等极端低温气候影响。"}], "cross_boundary_rule": "若内容涉及高原山区的冻土问题，若冻土是主要矛盾，可关联冰冻与严寒地区筑路；若地形高差是主要矛盾，主挂载本节点。若涉及岩溶，主挂载喀斯特地区筑路。"}]}
